export const tasksForRepro=key=>reproTasks[key];
export const validRepro=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];
export const advanceRepro=(route,step,choice)=>Number.isInteger(step)&&step>=0&&step<route.length&&choice===route[step]?step+1:step;
export const numericRepro=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;
export function cycleState(p=0){p=Math.max(0,Math.min(1,Number(p)||0));let phase=Math.min(3,Math.floor(p*4));return{phase,day:1+p*27,lining:phase===0?12-p*36:phase===1?3+(p-.25)*24:phase===2?9:11,eggReleased:p>=.5};}
export const ivfStage=p=>Math.min(4,Math.floor(Math.max(0,Math.min(1,Number(p)||0))*5));
export function curveValue(curve,day){day=Math.max(1,Math.min(28,Number(day)||1));let i=cycleDays.findIndex(d=>d>=day);if(i<=0)return curve[0];let p=(day-cycleDays[i-1])/(cycleDays[i]-cycleDays[i-1]);return curve[i-1]+(curve[i]-curve[i-1])*p;}
